import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const s="/assets/299_f5c9aca2-619e-431d-a7d8-f3dca4023836.BnEuyB3G.png",h=JSON.parse('{"title":"Dedicated Server Traffic Statistics","description":"","frontmatter":{"title":"Dedicated Server Traffic Statistics"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/dedicated-server-traffic-statistics.md","filePath":"operations-knowledge-base/dedicated-server/dedicated-server-traffic-statistics.md","lastUpdated":1794292919000}'),o={name:"operations-knowledge-base/dedicated-server/dedicated-server-traffic-statistics.md"};function n(d,t,c,f,l,u){return a(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="i-traffic-statistics" tabindex="-1"><strong>I. Traffic Statistics</strong> <a class="header-anchor" href="#i-traffic-statistics" aria-label="Permalink to &quot;**I. Traffic Statistics**&quot;">​</a></h2><p>In the client portal, you can view your server’s traffic usage over recent periods (such as the past month). The statistics clearly show inbound, outbound, and total traffic across different time ranges, including &quot;Today&quot;, &quot;Last 7 Days&quot;, &quot;This Month&quot;, and &quot;Last 30 Days&quot;. This helps you quickly understand and monitor your server’s traffic usage.</p><p><strong>1) Access Path:</strong> Log in to the platform and enter the <strong>Client Center</strong>. At the bottom, click <strong>“My Orders” → “Dedicated Servers.”</strong> Alternatively, go to <strong>“Product Management” → “Dedicated Servers.”</strong> On the <strong>Product Details</strong> page, find <strong>“Traffic Statistics”</strong> under the <strong>“Server Information”</strong> section.</p><p><img src="'+s+'" alt=""></p><h2 id="ii-traffic-overuse-alerts-and-handling" tabindex="-1"><strong>II. Traffic Overuse Alerts and Handling</strong> <a class="header-anchor" href="#ii-traffic-overuse-alerts-and-handling" aria-label="Permalink to &quot;**II. Traffic Overuse Alerts and Handling**&quot;">​</a></h2><p>When your server’s traffic quota is close to being used up, we will send you a notification via a support ticket. The ticket will include traffic-related details such as the hostname, dedicated IP, billing cycle, next billing date, bandwidth option, and the percentage of traffic already used.</p><p>If you do not upgrade your traffic quota after receiving the notification and the allocated traffic is fully consumed, the server will be automatically shut down at 12:00 AM (U.S. time). To avoid service interruptions caused by exceeding the traffic quota, we recommend upgrading to the next traffic tier in advance based on your actual usage needs.</p>',7)])])}const p=e(o,[["render",n]]);export{h as __pageData,p as default};
